<?php
declare(strict_types=1);
$app=require dirname(__DIR__,2).'/bootstrap.php';$user=$app['auth']->requireBusiness();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$statement=$app['pdo']->prepare('SELECT p.pdf_storage_key,p.serial_number FROM dbo.business_permits p JOIN dbo.business_user_links l ON l.business_id=p.business_id AND l.ended_at IS NULL WHERE p.id=:id AND l.user_id=:user');$statement->execute(['id'=>$id,'user'=>$user['id']]);$permit=$statement->fetch();if(!is_array($permit)){http_response_code(404);exit('Not found.');}$store=new App\Document\DocumentStore(dirname(__DIR__,2).'/var/documents');$path=$store->path((string)$permit['pdf_storage_key']);header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="leja-'.preg_replace('/[^A-Za-z0-9._-]/','-',(string)$permit['serial_number']).'.pdf"');header('Content-Length: '.filesize($path));header('Cache-Control: private, no-store');readfile($path);
